class Solution { public int maximumSafenessFactor(List<List<Integer>> grid){int n=grid.size();int[][] distance=new int[n][n];for(int[] row:distance)Arrays.fill(row,-1);Deque<int[]> queue=new ArrayDeque<>();for(int row=0;row<n;row++)for(int col=0;col<n;col++)if(grid.get(row).get(col)==1){distance[row][col]=0;queue.add(new int[]{row,col});}int[][] directions={{1,0},{-1,0},{0,1},{0,-1}};while(!queue.isEmpty()){int[] cell=queue.removeFirst();for(int[] direction:directions){int row=cell[0]+direction[0],col=cell[1]+direction[1];if(row>=0&&row<n&&col>=0&&col<n&&distance[row][col]==-1){distance[row][col]=distance[cell[0]][cell[1]]+1;queue.addLast(new int[]{row,col});}}}int[][] best=new int[n][n];for(int[] row:best)Arrays.fill(row,-1);PriorityQueue<int[]> heap=new PriorityQueue<>((a,b)->Integer.compare(b[0],a[0]));best[0][0]=distance[0][0];heap.add(new int[]{best[0][0],0,0});while(!heap.isEmpty()){int[] state=heap.poll();int safety=state[0],row=state[1],col=state[2];if(safety<best[row][col])continue;if(row==n-1&&col==n-1)return safety;for(int[] direction:directions){int nextRow=row+direction[0],nextCol=col+direction[1];if(nextRow>=0&&nextRow<n&&nextCol>=0&&nextCol<n){int candidate=Math.min(safety,distance[nextRow][nextCol]);if(candidate>best[nextRow][nextCol]){best[nextRow][nextCol]=candidate;heap.add(new int[]{candidate,nextRow,nextCol});}}}}return 0;} }
